#include <bits/stdc++.h>
using namespace std;
const long long mod=998244353;
int main() {
    
    int t;cin>>t;
    while(t--){
        int n;cin>>n;
        vector<vector<int>> at(n+1);
        for(int i=1;i<=n;i++){
            int k;cin>>k;
            at[k].push_back(i);
        }
        
        vector<int> dp(n+2,0);
        vector<int> dpp(n+2,0);
        dp[0]=1;
        for(int u=1;u<=n;u++){
            fill(dpp.begin(),dpp.begin()+u+1,0);
            for(int x=0;x<u;x++){
                if(dp[x]==0) continue;
                int y=u-1-x;
                for(int d=0;d<2;d++){
                    if(u==n&&d==1) break;
                    int pos;
                    if(d==0){
                        pos=x+1;
                    }
                    else{
                        pos=n-y;
                    }
                    bool val=true;
                    for(int i:at[u]){
                        bool gd=false;
                        if(pos<=i){
                            int hlf=(i+1)/2;
                            int cnt=min(x,i)+max(0,i-(n-y));
                            
                            if(cnt==hlf-1) gd=true;
                        }
                        if(!gd&&pos>=i){
                            int len=n-i+1;
                            int hlf=(len+1)/2;
                            int cnt=min(y,len)+max(0,x-i+1);
                            
                            if(cnt==hlf-1) gd=true;
                            
                        }
                        if(!gd){val=false;break;}
                        
                    }
                    if(!val) continue;
                    int nx;
                    if(d==0) nx=x+1;
                    else nx=x;
                    
                    dpp[nx]+=dp[x];
                    if(dpp[nx]>=mod) dpp[nx]-=mod;
                }
            }
            dp.swap(dpp);
        }
        long long ans=0;
        for(int x=0;x<=n;x++){
            ans+=dp[x];
        }
        cout<<ans%mod<<endl;
    }

}
